-- [row 264 · AUD-L3a-003 / AUD-L7-005] The database refuses an illegal order-status change,
-- and order_status_logs is append-only in the database, not only in one Prisma client.
--
-- 1. orders_status_transition_guard: an UPDATE that changes "status" must be an edge of
--    ORDER_TRANSITIONS (the forward machine) or RECOVERY_TRANSITIONS (the release edges) in
--    apps/api/src/modules/order/order-status.ts. The edge list below is GENERATED by
--    orderStatusGuardDdl() in src/modules/order/order-status-guard.ts and is never edited by
--    hand; order-status-db-guard.test.ts proves the live database accepts exactly those pairs.
--    A write that leaves "status" unchanged is not judged. INSERT is not judged (an order may
--    be created in any state; this guards CHANGES).
-- 2. order_status_logs_append_only: UPDATE and DELETE are refused for every connection. A row
--    leaves only with its order: the foreign key cascade (ON DELETE CASCADE) deletes it from
--    inside its own trigger, after the order row is gone.
--
-- No backfill: no existing row is judged, only future changes. Rollback: rollback.sql beside
-- this file (drops exactly the two triggers and two functions, and this ledger row).
-- lock_timeout: the trigger DDL locks "orders" and "order_status_logs"; behind a long
-- transaction the deploy gives up after 10 s (nothing applied) instead of holding every order
-- read and write in line behind it.
SET lock_timeout = '10s';
CREATE OR REPLACE FUNCTION orders_status_transition_guard() RETURNS trigger AS $$
BEGIN
  IF (OLD."status"::text || '>' || NEW."status"::text) = ANY (ARRAY['PENDING>ACCEPTED', 'ACCEPTED>PREPARING', 'PREPARING>READY_FOR_PICKUP', 'ACCEPTED>RIDER_ASSIGNED', 'PREPARING>RIDER_ASSIGNED', 'READY_FOR_PICKUP>RIDER_ASSIGNED', 'RIDER_ASSIGNED>RIDER_EN_ROUTE_PICKUP', 'RIDER_ASSIGNED>RIDER_ARRIVED_PICKUP', 'RIDER_EN_ROUTE_PICKUP>RIDER_ARRIVED_PICKUP', 'READY_FOR_PICKUP>PICKED_UP', 'RIDER_ASSIGNED>PICKED_UP', 'RIDER_EN_ROUTE_PICKUP>PICKED_UP', 'RIDER_ARRIVED_PICKUP>PICKED_UP', 'PICKED_UP>EN_ROUTE_DELIVERY', 'PICKED_UP>ARRIVED', 'EN_ROUTE_DELIVERY>ARRIVED', 'PENDING>DRIVER_ASSIGNED', 'DRIVER_ASSIGNED>DRIVER_EN_ROUTE', 'DRIVER_EN_ROUTE>DRIVER_ARRIVED', 'DRIVER_ARRIVED>RIDE_IN_PROGRESS', 'PICKED_UP>DELIVERED', 'EN_ROUTE_DELIVERY>DELIVERED', 'ARRIVED>DELIVERED', 'RIDE_IN_PROGRESS>DELIVERED', 'READY_FOR_PICKUP>DELIVERED', 'DELIVERED>COMPLETED', 'READY_FOR_PICKUP>COMPLETED', 'ACCEPTED>COMPLETED', 'PENDING>CANCELLED', 'ACCEPTED>CANCELLED', 'PREPARING>CANCELLED', 'READY_FOR_PICKUP>CANCELLED', 'RIDER_ASSIGNED>CANCELLED', 'RIDER_EN_ROUTE_PICKUP>CANCELLED', 'RIDER_ARRIVED_PICKUP>CANCELLED', 'DRIVER_ASSIGNED>CANCELLED', 'DRIVER_EN_ROUTE>CANCELLED', 'DRIVER_ARRIVED>CANCELLED', 'CANCELLED>REFUNDED', 'DELIVERED>REFUNDED', 'COMPLETED>REFUNDED', 'ARRIVED>FAILED', 'RIDE_IN_PROGRESS>FAILED', 'PICKED_UP>FAILED', 'EN_ROUTE_DELIVERY>FAILED', 'PICKED_UP>RETURNING', 'EN_ROUTE_DELIVERY>RETURNING', 'ARRIVED>RETURNING', 'RETURNING>RETURNED']::text[]) THEN
    RETURN NEW;
  END IF;
  IF (OLD."status"::text || '>' || NEW."status"::text) = ANY (ARRAY['DRIVER_ASSIGNED>PENDING', 'DRIVER_EN_ROUTE>PENDING', 'DRIVER_ARRIVED>PENDING', 'RIDER_ASSIGNED>ACCEPTED', 'RIDER_EN_ROUTE_PICKUP>ACCEPTED', 'RIDER_ARRIVED_PICKUP>ACCEPTED', 'RIDER_ASSIGNED>PREPARING', 'RIDER_EN_ROUTE_PICKUP>PREPARING', 'RIDER_ARRIVED_PICKUP>PREPARING', 'RIDER_ASSIGNED>READY_FOR_PICKUP', 'RIDER_EN_ROUTE_PICKUP>READY_FOR_PICKUP', 'RIDER_ARRIVED_PICKUP>READY_FOR_PICKUP']::text[]) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'ORDER_STATUS_ILLEGAL: order % cannot move from % to %: not an edge of ORDER_TRANSITIONS or RECOVERY_TRANSITIONS [row 264]',
    OLD."id", OLD."status", NEW."status" USING ERRCODE = 'check_violation';
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS orders_status_transition_guard ON "orders";
CREATE TRIGGER orders_status_transition_guard BEFORE UPDATE ON "orders" FOR EACH ROW WHEN (OLD."status" IS DISTINCT FROM NEW."status") EXECUTE FUNCTION orders_status_transition_guard();
CREATE OR REPLACE FUNCTION order_status_logs_append_only() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1
     AND NOT EXISTS (SELECT 1 FROM "orders" o WHERE o."id" = OLD."orderId") THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'ORDER_STATUS_LOG_APPEND_ONLY: order_status_logs row % is immutable evidence; % is refused (it leaves only with its order) [row 264]',
    OLD."id", TG_OP USING ERRCODE = 'check_violation';
END $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS order_status_logs_append_only ON "order_status_logs";
CREATE TRIGGER order_status_logs_append_only BEFORE UPDATE OR DELETE ON "order_status_logs" FOR EACH ROW EXECUTE FUNCTION order_status_logs_append_only();
